yaml_template:
name: stage-review-Secure-Access-Suspicious-User-Agent-Combo
visualization:
  options:
    columns:
    - fieldName: '@timestamp'
      format: datetime
      type: field
      width: 200
    - groupByPrefix: false
      header: Field List
      type: fieldList
    newestAtBottom: true
    showOnlyFirstLine: false
  type: list-view
labels:
- daac
- pdl
- bk1191
$schema: https://schemas.humio.com/query/v0.6.0
timeInterval:
  isLive: false
  start: 15m
queryString: |-
  // RULE NAME: Secure-Access-Suspicious-User-Agent-Combo

  // ============================================================
  // SECTION 1: Log Source Fields (tagged fields for filtering - improves performance)
  // ============================================================
  lab.source = *studentid* #type = "studentid-secure-access-syslog"

  // ============================================================
  // SECTION 2: CPS Category Fields (tagged fields for filtering - improves performance)
  // ============================================================
  | #event.kind="event" #event.outcome="success"

  // ============================================================
  // SECTION 3: Query Target (specific logic core to use case)
  // ============================================================
  // Create a user agent combo identifier
  // Create a user agent combo identifier
  | user_agent_combo := format("%s on %s", field=[user_agent.name, user_agent.device.name])

  // Flag patterns that are ACTUALLY unusual/suspicious in your data:
  | case {
      // Generic/Unknown browser or device (could indicate spoofing or automation)
      user_agent.name = "Generic" | anomaly_type := "Generic/Unknown Browser";
      user_agent.device.name = "Generic" | anomaly_type := "Generic/Unknown Device";

      // Mobile Safari accessing enterprise apps (less common, could be BYOD risk)
      user_agent.name = "Safari" AND user_agent.device.name = "Mobile" | anomaly_type := "Mobile Safari Access";

      // Tablet access (unusual for enterprise work, could be personal device)
      user_agent.device.name = "Tablet" | anomaly_type := "Tablet Device Access";

      // Desktop Safari (uncommon in Windows-heavy enterprises)
      user_agent.name = "Safari" AND user_agent.device.name = "Desktop" | anomaly_type := "Desktop Safari (Mac)";

      // Everything else
      * | anomaly_type := "Normal Desktop Browser";
  }

  // Show only the anomalous patterns
  | anomaly_type != "Normal Desktop Browser"

  // ============================================================
  // SECTION 4: Aggregation / Grouping (if needed)
  // ============================================================
  | groupBy([user.name, anomaly_type], function=[
      count(as=access_count),
      collect([user_agent_combo, service.name, event.action, source.ip, source.geo.city_name], limit=10)
    ])

  // ============================================================
  // SECTION 5: Exclusions + Threshold Filtering
  // ============================================================
  // Sort by most frequent anomalies
  | sort(access_count, order=desc)

  // ============================================================
  // SECTION 6: Rule Notes
  // ============================================================
